"""Compose aggregate44 source + guarded7.3packetABI + independentlyportedproviders."""
import argparse,hashlib,json,shutil
from pathlib import Path
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--aggregate',type=Path,required=True);p.add_argument('--kernel-candidate',type=Path,required=True);p.add_argument('--providers',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();kernel=json.loads((a.kernel_candidate/'result.json').read_text());providers=json.loads((a.providers/'result.json').read_text());a.output.mkdir(parents=True);shutil.copytree(a.aggregate/'source',a.output/'source');shutil.copytree(a.aggregate/'headers',a.output/'headers');shutil.copytree(a.kernel_candidate/'kernel-overlay',a.output/'kernel-overlay');shutil.copyfile(a.kernel_candidate/'kernel73-overlay.patch',a.output/'kernel73-overlay.patch');applied=[]
 for rel,h in providers['files'].items():
  path=a.providers/Path(rel.replace('\\','/'));assert sha(path)==h;target=a.output/Path(rel.replace('\\','/'));target.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(path,target);applied.append(str(target.relative_to(a.output)))
 # Provideroverlay'scommoncompatfile camefromanothermergedlineage; verify suffix
