 compat=a.output/'source/qdrv/compat/include/openmitrastar_qdrv_compat.h';t=compat.read_text();t=t.replace('#include <linux/fs.h>','#include <linux/fs.h>\n#include <linux/interrupt.h>\n#include <linux/string.h>',1);compat.write_text(t,newline='\n')
 mk=(a.kernel_candidate/'Kbuild').read_text();mk=mk.replace('-Wno-error=implicit-function-declaration','-Werror=implicit-function-declaration').replace('-Wall -Wno-error -Wno-unused-function','-Wall -Wno-unused-function');mk+='\nccflags-y += -I$(src)/providers/include\nqtn73_support-y := providers/qtn_pm_qos_compat.o providers/qtn_platform_support.o providers/board_compat.o providers/runtime_compat.o\nobj-m += qtn73_support.o\n';(a.output/'Kbuild').write_text(mk,newline='\n');files={str(x.relative_to(a.output)):sha(x)for group in('source','headers','kernel-overlay','providers')for x in(a.output/group).rglob('*')if x.is_file()};result=dict(kernel);result.update(status='SOURCE_ONLY_LINUX73_FULL44_WITH_COMPAT_PROVIDERS_PENDING_FRESH_BUILD',parent=str(a.aggregate),parent_result_sha256=sha(a.aggregate/'result.json'),provider_result_sha256=sha(a.providers/'result.json'),provider_files=applied,files=files,kbuild_sha256=sha(a.output/'Kbuild'),old_5_10_objects_used=False,Linux73_qualified_records=0,limits=['Aggregate610table sourceonlynotfunctionalqualification.','Allmodule/kernelobjects mustfreshbuildwithnewpacketABI; no importedprovider.ko/.o.','Implicitdeclarations arecompileerrors, historicalwarningdiagnostics retained.','Realproviderexports/customsharedtables/DT/IOCTL/MuC semantics requirejointclosure/physicaltests.','Nohardware.']);(a.output/'result.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'status':result['status'],'source_files':len(files),'kbuild_sha256':result['kbuild_sha256'],'provider_files':applied},indent=2))
